//! The pull-request integration stack's first-party root: the public key of a published test seed
//! (`ci_first_party_root.seed`, committed beside this file). Anyone can sign with that seed, so a
//! build that trusted this key would accept anything as first-party: it is compiled only with the
//! `ci-first-party-root` feature, which `build.rs` refuses for a deploy (`CITADEL_DEPLOY`) and for
//! wasm32, and which only the integration image's kernel stage enables
//! (`docker/workspace-server/Dockerfile`, `scripts/check-ci-first-party-root-stays-in-ci.mjs`).
//! Unit tests compile it too, to hold it to its seed and keep it out of the production list.

use super::install::FIRST_PARTY_PUBLISHER_KEYS;

/// The test seed's ML-DSA-65 key (fingerprint `78ca c1b3 d875 da14`).
pub const CI_FIRST_PARTY_PUBLISHER_KEYS: &[&str] = &[""];

/// The production keys, then the CI root's: the trusted set of a build with the feature.
pub const WITH_PRODUCTION: [&str;
    FIRST_PARTY_PUBLISHER_KEYS.len() + CI_FIRST_PARTY_PUBLISHER_KEYS.len()] =
    joined(FIRST_PARTY_PUBLISHER_KEYS, CI_FIRST_PARTY_PUBLISHER_KEYS);

const fn joined<const N: usize>(
    first: &[&'static str],
    then: &[&'static str],
) -> [&'static str; N] {
    let mut out = [""; N];
    let mut i = 0;
    while i < first.len() {
        out[i] = first[i];
        i += 1;
    }
    let mut j = 0;
    while j < then.len() {
        out[first.len() + j] = then[j];
        j += 1;
    }
    out
}
